package com.tekwatt.support.controller;import com.tekwatt.support.dto.*;import com.tekwatt.support.entity.*;import com.tekwatt.support.service.SupportTicketService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/support/tickets")public class SupportTicketController{private final SupportTicketService service;public SupportTicketController(SupportTicketService s){service=s;}@PostMapping@ResponseStatus(HttpStatus.CREATED)SupportTicket create(@Valid@RequestBody CreateTicketRequest r){return service.create(r);}@GetMapping List<SupportTicket>list(@RequestParam UUID tenantId,@RequestParam(required=false)TicketStatus status){return service.list(tenantId,status);}@GetMapping("/{id}")TicketDetailResponse detail(@PathVariable UUID id){return service.detail(id);}@PatchMapping("/{id}/assignment")SupportTicket assign(@PathVariable UUID id,@Valid@RequestBody AssignTicketRequest r){return service.assign(id,r);}@PatchMapping("/{id}/priority")SupportTicket priority(@PathVariable UUID id,@Valid@RequestBody UpdatePriorityRequest r){return service.priority(id,r);}@PatchMapping("/{id}/status")SupportTicket status(@PathVariable UUID id,@Valid@RequestBody UpdateStatusRequest r){return service.status(id,r);}@PostMapping("/{id}/comments")@ResponseStatus(HttpStatus.CREATED)TicketComment comment(@PathVariable UUID id,@Valid@RequestBody AddCommentRequest r){return service.comment(id,r);}}
